     * A custom function to create a new key in the database or
     * other source
     *
     * This will override the default createJwk from the database
     *
     * @param data - The key to create
     * @returns The created key
     */
    createJwk?: (data: Omit<Jwk, "id">, ctx: GenericEndpointContext) => Promise<Jwk>;
  };
}
/**
 * Asymmetric (JWS) Supported.
 *
 * @see https://github.com/panva/jose/issues/210
 */
type JWKOptions = {
  alg: "EdDSA";
  crv?: "Ed25519" | undefined;
} | {
  alg: "ES256";
  crv?: never | undefined;
} | {
  alg: "ES512";
  crv?: never | undefined;
} | {
  alg: "PS256";
  modulusLength?: number | undefined;
} | {
  alg: "RS256";
  modulusLength?: number | undefined;
};
type JWSAlgorithms = JWKOptions["alg"];
interface Jwk {
  id: string;
  publicKey: string;
  privateKey: string;
  createdAt: Date;
  expiresAt?: Date;
  alg?: JWSAlgorithms | undefined;
  crv?: ("Ed25519" | "P-256" | "P-521") | undefined;
}
/**
 * A fully resolved signing key ready for JWT signing.
 * Produced by `resolveSigningKey`, consumed by `signJWT`.
 * Separates key resolution from signing so callers can
 * read the `alg` before constructing the JWT payload
 * (required for OIDC hash claims like at_hash).
 */
interface ResolvedSigningKey {
  alg: string;
  kid: string;
  privateKey: CryptoKey | Uint8Array;
}
//#endregion
export { JWKOptions, JWSAlgorithms, Jwk, JwtOptions, ResolvedSigningKey };

